"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useDispatch } from "react-redux";
import { useState } from "react";
import axios from "axios";
import { setCurrentUser } from "../reducer";
import { FormControl, Button, Alert } from "react-bootstrap";
import * as client from "../../client";

type Credentials = {
  username?: string;
  password?: string;
  verifyPassword?: string;
};

export default function Signup() {
  const [credentials, setCredentials] = useState<Credentials>({});
  const [error, setError] = useState("");
  const dispatch = useDispatch();
  const router = useRouter();

  const signup = async () => {
    setError("");
    const { username, password, verifyPassword } = credentials;
    if (!username || !password) {
      setError("Username and password are required");
      return;
    }
    if (password !== verifyPassword) {
      setError("Passwords do not match");
      return;
    }
    try {
      const user = await client.signup({ username, password });
      if (!user) {
        setError("Sign up failed");
        return;
      }
      dispatch(setCurrentUser(user));
      router.push("/account/profile");
    } catch (e: unknown) {
      if (axios.isAxiosError(e)) {
        setError((e.response?.data as { message?: string })?.message || "Unable to sign up");
      } else {
        setError("Unable to sign up");
      }
    }
  };

  return (
    <div
      id="wd-signup-screen"
      className="d-flex justify-content-center mt-5"
    >
      <div style={{ width: "300px" }}>
        <h3 className="mb-3">Sign up</h3>

        <FormControl
          value={credentials.username || ""}
          onChange={(e) => setCredentials({ ...credentials, username: e.target.value })}
          placeholder="Username"
          className="mb-2"
          id="wd-username"
        />

        <FormControl
          value={credentials.password || ""}
          onChange={(e) => setCredentials({ ...credentials, password: e.target.value })}
          type="password"
          placeholder="Password"
          className="mb-2"
          id="wd-password"
        />

        <FormControl
          value={credentials.verifyPassword || ""}
          onChange={(e) => setCredentials({ ...credentials, verifyPassword: e.target.value })}
          type="password"
          placeholder="Verify Password"
          className="mb-3"
          id="wd-verify-password"
        />

        {error && <Alert variant="danger" className="mb-2">{error}</Alert>}

        <Button
          onClick={signup}
          className="w-100 mb-3"
          id="wd-signup-btn"
        >
          Sign up
        </Button>

        <div className="text-center">
          <Link
            href="/account/signin"
            className="text-decoration-none"
          >
            Sign in
          </Link>
        </div>
      </div>
    </div>
  );
}
